// csilEncReceipt builds the canonical CBOR value tree for a Receipt.
func csilEncReceipt(csilV Receipt) cborValue {
	csilEntries := make(cborMap, 0, 10)
	csilEntries = append(csilEntries, cborEntry{cborText("ref"), csilEncRecordRef(csilV.Ref)})
	csilEntries = append(csilEntries, cborEntry{cborText("actor"), csilEncIdentityRef(csilV.Actor)})
	if csilV.Error != nil {
		csilEntries = append(csilEntries, cborEntry{cborText("error"), csilEncServiceError((*csilV.Error))})
	}
	csilEntries = append(csilEntries, cborEntry{cborText("state"), cborText(csilV.State)})
	if csilV.Result != nil {
		csilEntries = append(csilEntries, cborEntry{cborText("result"), csilEncTypedPayload((*csilV.Result))})
	}
	csilEntries = append(csilEntries, cborEntry{cborText("operation"), csilEncOperationRef(csilV.Operation)})
	csilEntries = append(csilEntries, cborEntry{cborText("command_id"), cborText(csilV.CommandId)})
	csilEntries = append(csilEntries, cborEntry{cborText("recorded_at"), csilEncTimestamp(csilV.RecordedAt)})
	csilEntries = append(csilEntries, cborEntry{cborText("input_digest"), cborBytes(csilV.InputDigest)})
	if csilV.PriorReceipt != nil {
		csilEntries = append(csilEntries, cborEntry{cborText("prior_receipt"), csilEncRecordRef((*csilV.PriorReceipt))})
	}
	return csilEntries
}

// csilDecReceipt reconstructs a Receipt from a decoded CBOR value tree.
func csilDecReceipt(csilRoot cborValue) (Receipt, error) {
	var csilOut Receipt
	{
		csilField, csilErr := cborRequire(csilRoot, "ref")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (csilDecRecordRef)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.Ref = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "command_id")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (cborAsText)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.CommandId = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "actor")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (csilDecIdentityRef)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.Actor = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "operation")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (csilDecOperationRef)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.Operation = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "input_digest")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (cborAsBytes)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.InputDigest = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "state")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (func(csilV cborValue) (ReceiptState, error) {
			csilInner, csilErr := (func(csilV cborValue) (string, error) {
				csilInner, csilErr := (cborAsText)(csilV)
				if csilErr != nil {
					var csilZero string
					return csilZero, csilErr
				}
				if !(csilInner == "accepted" || csilInner == "completed" || csilInner == "rejected" || csilInner == "outcome_unknown") {
					var csilZero string
					return csilZero, fmt.Errorf("csil cbor: value %v is not a member of the declared enum", csilInner)
				}
				return csilInner, nil
			})(csilV)
			return ReceiptState(csilInner), csilErr
		})(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.State = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "recorded_at")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (csilAsTimestamp)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.RecordedAt = csilVal
	}
	if csilField, csilOk := cborMapGet(csilRoot, "result"); csilOk {
		csilVal, csilErr := (csilDecTypedPayload)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.Result = &csilVal
	}
	if csilField, csilOk := cborMapGet(csilRoot, "prior_receipt"); csilOk {
		csilVal, csilErr := (csilDecRecordRef)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.PriorReceipt = &csilVal
	}
	if csilField, csilOk := cborMapGet(csilRoot, "error"); csilOk {
		csilVal, csilErr := (csilDecServiceError)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.Error = &csilVal
	}
	return csilOut, nil
}

