// csilEncConversationHistory builds the canonical CBOR value tree for a ConversationHistory.
func csilEncConversationHistory(csilV ConversationHistory) cborValue {
	csilEntries := make(cborMap, 0, 5)
	csilEntries = append(csilEntries, cborEntry{cborText("limit"), cborUint(csilV.Limit)})
	csilEntries = append(csilEntries, cborEntry{cborText("owner"), csilEncScopeRef(csilV.Owner)})
	csilEntries = append(csilEntries, cborEntry{cborText("session_id"), cborText(csilV.SessionId)})
	csilEntries = append(csilEntries, cborEntry{cborText("after_sequence"), cborUint(csilV.AfterSequence)})
	if csilV.BeforeSequence != nil {
		csilEntries = append(csilEntries, cborEntry{cborText("before_sequence"), cborUint((*csilV.BeforeSequence))})
	}
	return csilEntries
}

// csilDecConversationHistory reconstructs a ConversationHistory from a decoded CBOR value tree.
func csilDecConversationHistory(csilRoot cborValue) (ConversationHistory, error) {
	var csilOut ConversationHistory
	{
		csilField, csilErr := cborRequire(csilRoot, "owner")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (csilDecScopeRef)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.Owner = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "session_id")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (cborAsText)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.SessionId = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "after_sequence")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (cborAsU64)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.AfterSequence = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "limit")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (cborAsU64)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.Limit = csilVal
	}
	if csilField, csilOk := cborMapGet(csilRoot, "before_sequence"); csilOk {
		csilVal, csilErr := (cborAsU64)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.BeforeSequence = &csilVal
	}
	return csilOut, nil
}

